import json,urllib.parse,urllib.request,time,sys
Q=["Calendar of the Stuart Papers belonging to His Majesty","Thurloe state papers","Calendar of the manuscripts of the Marquis of Ormonde","Carte papers Ormonde letters","Calendar of Treasury Papers","Calendar of Treasury Books","Calendar of Clarendon State Papers","Historical Manuscripts Commission report manuscripts Rutland","manuscripts of the Duke of Portland","manuscripts of the late Reginald Rawdon Hastings","Buccleuch Montagu House manuscripts","manuscripts of the Marquis of Downshire","Lonsdale manuscripts Historical Manuscripts Commission","Earl Cowper Coke Melbourne manuscripts","manuscripts of the Earl of Egmont","Stopford-Sackville manuscripts","Report on manuscripts in various collections","manuscripts of the Earl of Mar and Kellie","Hamilton manuscripts Historical Manuscripts Commission","Calendar of State Papers Colonial America and West Indies","Calendar of State Papers relating to Ireland","Calendar of State Papers relating to Scotland","Calendar of letters and papers relating to the affairs of the borders of England and Scotland","Report on the manuscripts of the late Allan George Finch","Calendar of the Carew manuscripts","Nicholas papers Camden Society","Egerton papers Camden Society","Hardwicke state papers Miscellaneous","Historical records of the Royal Society","Calendar of Home Office Papers","Journals of the Continental Congress","Official Records of the Union and Confederate Navies","War of the Rebellion official records","Historical Manuscripts Commission report Marquess of Salisbury","Report on the manuscripts of Lord de L'Isle and Dudley","Report on the manuscripts of the Earl of Denbigh","Report on manuscripts Marquess of Bath Longleat","Report on the manuscripts of Allan Finch","Manuscripts of J. B. Fortescue Dropmore","Manuscripts of the Marquess of Ormonde new series","Report on manuscripts of the Duke of Leeds","Report on the manuscripts of Mrs Stopford-Sackville","Report on the manuscripts of the Earl of Westmorland","Report on the Laing manuscripts Edinburgh","Report on the manuscripts of Lord Polwarth","Report on the manuscripts of the Marquess of Lothian","Report on the manuscripts of the Duke of Athole Earl of Home","Report on the manuscripts of Colonel David Milne Home","Report on the manuscripts of the Earl of Eglinton","Report on manuscripts of the Right Hon. F. J. Savile Foljambe","Report on the manuscripts of the Marquess of Downshire","Report on the manuscripts of Lady Du Cane","Report on the manuscripts of the late Montagu Bertie Earl of Lindsey","Report on the manuscripts of Mrs Frankland-Russell-Astley","Report on the manuscripts of the Earl of Ancaster","Report on American manuscripts in the Royal Institution","Report on the manuscripts of Reginald Fleming Hodgson","Report on the manuscripts of F. W. Leyborne-Popham","Report on the manuscripts of the Duke of Buccleuch Queensberry Drumlanrig","Report on the manuscripts of the Marquis of Lothian Blickling","Report on the manuscripts of the Corporation of Dartmouth","Report on the manuscripts of Sir William Fitzherbert Bart Cavendish","Report on the Pepys manuscripts","Report on manuscripts Ormonde Kilkenny Castle","Papers of the Continental Congress","Calendar of State Papers Domestic Charles II","Calendar of State Papers Domestic Anne","Calendar of State Papers Domestic William III","Calendar of State Papers Domestic James I","Calendar of State Papers Domestic Charles I","Calendar of State Papers Domestic Commonwealth","Calendar of State Papers Domestic Elizabeth"]
out={}
for q in Q:
    u="https://archive.org/advancedsearch.php?q=%s&fl[]=identifier&fl[]=title&fl[]=date&fl[]=imagecount&rows=40&output=json"%urllib.parse.quote('title:(%s) AND mediatype:texts'%q)
    try:
        d=json.load(urllib.request.urlopen(urllib.request.Request(u,headers={"User-Agent":"Mozilla/5.0"}),timeout=60))
        for x in d["response"]["docs"]: out[x["identifier"]]={"title":x.get("title"),"date":x.get("date"),"n":x.get("imagecount"),"q":q}
        print(q,len(d["response"]["docs"]),flush=True)
    except Exception as e: print("fail",q,e,flush=True)
    time.sleep(1)
json.dump(out,open("ids.json","w"),indent=0)
